import{_ as i,c as l,o as e,aj as r,ao as t,ap as s,aq as h,ar as o,as as n,at as d,au as m,av as c,aw as p,ax as _,ay as b,az as u,aA as g}from"./chunks/framework.C9rMrtxb.js";const y=JSON.parse('{"title":"输入节点","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"node-input.md","filePath":"node-input.md"}'),f={name:"node-input.md"};function x(P,a,k,N,S,X){return e(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="输入节点" tabindex="-1">输入节点 <a class="header-anchor" href="#输入节点" aria-label="Permalink to “输入节点”">​</a></h1><p>输入节点通常为用于输入信息到蓝图中，是蓝图逻辑的触发入口，比如输入一个数值</p><h2 id="数值" tabindex="-1">数值 <a class="header-anchor" href="#数值" aria-label="Permalink to “数值”">​</a></h2><p><img src="'+t+'" alt="valuenode image"> 输出一个数，可点击输入想要的数值，也可以点击左右箭头修改数值</p><h2 id="文字" tabindex="-1">文字 <a class="header-anchor" href="#文字" aria-label="Permalink to “文字”">​</a></h2><p><img src="'+s+'" alt="stringnode image"> 输出一段文本，可点击输入文本内容</p><h2 id="布尔值" tabindex="-1">布尔值 <a class="header-anchor" href="#布尔值" aria-label="Permalink to “布尔值”">​</a></h2><p><img src="'+h+'" alt="boolennode image"> 输出一个状态开或者关，点击可切换开关</p><h2 id="开始时" tabindex="-1">开始时 <a class="header-anchor" href="#开始时" aria-label="Permalink to “开始时”">​</a></h2><p><img src="'+o+'" alt="startnode image"> 可选三个输出时机触发</p><ul><li>开始前，所有物体节点初始化阶段，此时物体还在加载资源，如涉及物体动画播放等操作，不要在此时执行</li><li>开始时，所有物体节点已经初始化完成，可以操作物体，但剩余节点不一定都初始化完成</li><li>开始后，所有节点已经初始化完成，并且分镜运行了一帧</li></ul><h2 id="按下按键" tabindex="-1">按下按键 <a class="header-anchor" href="#按下按键" aria-label="Permalink to “按下按键”">​</a></h2><h3 id="按钮" tabindex="-1">按钮 <a class="header-anchor" href="#按钮" aria-label="Permalink to “按钮”">​</a></h3><p><img src="'+n+'" alt="btnnode image"> 生成一个可以在蓝图中点击的按钮，点击时触发</p><h3 id="摇杆" tabindex="-1">摇杆 <a class="header-anchor" href="#摇杆" aria-label="Permalink to “摇杆”">​</a></h3><p><img src="'+d+'" alt="yaoganNode image"> 生成一个可以在蓝图中控制的摇杆，可以控制上下左右，当触发时输出</p><h2 id="触摸屏" tabindex="-1">触摸屏 <a class="header-anchor" href="#触摸屏" aria-label="Permalink to “触摸屏”">​</a></h2><h3 id="触摸开始" tabindex="-1">触摸开始 <a class="header-anchor" href="#触摸开始" aria-label="Permalink to “触摸开始”">​</a></h3><p><img src="'+m+'" alt="touchStartNode image"></p><ul><li>物体：当未关联物体时，监听的是屏幕触摸开始，关联物体时，监听的是物体触摸开始</li><li>监听：触发后开始监听事件</li><li>取消监听：触发后停止监听事件</li><li>开始X：输出触摸开始时的X轴坐标</li><li>开始Y：输出触摸开始时的Y轴坐标</li><li>点击：触摸开始时触发</li><li>控制物体的位置：激活后，如果当前有关联物体，将自动修改物体的位置到触摸的位置</li></ul><h3 id="触摸移动" tabindex="-1">触摸移动 <a class="header-anchor" href="#触摸移动" aria-label="Permalink to “触摸移动”">​</a></h3><p><img src="'+c+'" alt="touchmoveNode image"></p><ul><li>物体：当未关联物体时，监听的是屏幕触摸移动，关联物体时，监听的是物体触摸移动</li><li>监听：触发后开始监听事件</li><li>取消监听：触发后停止监听事件</li><li>X轴移动：输出触摸移动时的X轴坐标</li><li>Y轴移动：输出触摸移动时的Y轴坐标</li><li>移动：触摸移动时触发</li><li>控制物体的位置：激活后，如果当前有关联物体，将自动修改物体的位置到触摸的位置</li><li>碰撞框检测：激活后，如果当前有关联物体，且物体有碰撞框，只有触摸位置在碰撞框内才会触发触摸移动</li><li>忽略多点触摸：激活后，当有多个触摸点时，忽略响应</li></ul><h3 id="触摸结束" tabindex="-1">触摸结束 <a class="header-anchor" href="#触摸结束" aria-label="Permalink to “触摸结束”">​</a></h3><p><img src="'+p+'" alt="touchendNode image"></p><ul><li>物体：当未关联物体时，监听的是屏幕触摸移动，关联物体时，监听的是物体触摸结束</li><li>监听：触发后开始监听事件</li><li>取消监听：触发后停止监听事件</li><li>结束X：输出触摸结束时的X轴坐标</li><li>结束Y：输出触摸结束时的Y轴坐标</li><li>结束：触摸结束时触发</li><li>点击结束：如果此次触摸从开始到结束，未发生触摸移动时触发</li><li>移动结束：如果此次触摸从开始到结束，发生了触摸移动时触发</li><li>控制物体的位置：激活后，如果当前有关联物体，将自动修改物体的位置到触摸的位置</li><li>响应触摸取消：激活后，如果触摸结束时的触摸位置在物体之外，也将触发触摸结束事件</li></ul><h2 id="获取数据" tabindex="-1">获取数据 <a class="header-anchor" href="#获取数据" aria-label="Permalink to “获取数据”">​</a></h2><h3 id="系统数据" tabindex="-1">系统数据 <a class="header-anchor" href="#系统数据" aria-label="Permalink to “系统数据”">​</a></h3><p><img src="'+_+'" alt="systemdataNode image"></p><ul><li>类型：可选择一些已经预置的系统数值 <ul><li>时间戳-秒：返回当前时间戳，精确到秒</li><li>年：月：日：返回当前日期</li><li>时：分：秒：返回当前时间</li><li>时：分：返回当前时间，不含秒</li><li>系统：返回当前设备的系统</li><li>版本：返回当前应用的版本</li><li>配置表：获取应用中的配置表</li><li>Object：返回一个空对象</li><li>Array：返回一个空数组</li><li>空间宽度：返回当前运行界面的宽度</li><li>空间高度：返回当前运行界面的高度</li><li>空间X轴范围：返回当前运行界面的X轴范围</li><li>空间Y轴范围：返回当前运行界面的Y轴范围</li></ul></li><li>表名称：如果选择类型为配置表，填写表名称后可以获取应用中的配置表</li></ul><h3 id="自定义数据" tabindex="-1">自定义数据 <a class="header-anchor" href="#自定义数据" aria-label="Permalink to “自定义数据”">​</a></h3><p><img src="'+b+'" alt="getCusDataNode image"> 获取一个记录在本地持久化储存中的自定义数据</p><ul><li>数据Key：数据保存在本地的名称，一般为英文</li><li>默认类型：当本地没有此数据的记录时，默认创建的数据类型</li><li>默认值：当本地没有此数据的记录时，默认创建的数据值，如果是字典或数组类型，将对默认值进行JSON.parse()操作</li></ul><p>要保存自定义数据到本地，请参考输出节点的<a href="./node-output.html#保存自定义数据">保存自定义数据</a></p><h2 id="重力感应" tabindex="-1">重力感应 <a class="header-anchor" href="#重力感应" aria-label="Permalink to “重力感应”">​</a></h2><p><img src="'+u+'" alt="gravyNode image"> 获取当前设备的重力感应值，如果设备不支持重力感应，所有轴的值将默认输出为0，如果支持，xyz轴的值应该输出为[-1，1]之间</p><h2 id="屏幕适配" tabindex="-1">屏幕适配 <a class="header-anchor" href="#屏幕适配" aria-label="Permalink to “屏幕适配”">​</a></h2><p><img src="'+g+'" alt="screenSize image"> 当蓝图运行时，屏幕适配会根据当前运行的窗口比例触发对应输出</p><ul><li>4:3通常为pad的尺寸</li><li>16:9为常规显示器的尺寸</li><li>18:9为全面屏手机的尺寸</li></ul>',39)])])}const v=i(f,[["render",x]]);export{y as __pageData,v as default};
